sksl:
uniform shader image;
uniform float2 size;
uniform float time;
uniform float2 layer;
uniform float3x3 toLayer;
uniform float left;
uniform float top;
uniform float right;
uniform float bottom;
uniform float radius;
uniform float feather;
half4 main(float2 coord) {
    if (left <= 0.0 && top <= 0.0 && right <= 0.0 && bottom <= 0.0 && radius <= 0.0 && feather <= 0.0) return image.eval(coord);
    float3 h = toLayer * float3(coord, 1.0);
    float2 p = h.xy / h.z;
    float2 lo = clamp(float2(left, top), 0.0, 0.999);
    float2 hi = max(1.0 - clamp(float2(right, bottom), 0.0, 1.0), lo + 0.001);
    float2 a = lo * layer;
    float2 b = hi * layer;
    float2 e = (b - a) * 0.5;
    float r = clamp(radius, 0.0, 1.0) * min(e.x, e.y);
    float2 q = abs(p - (a + b) * 0.5) - e + r;
    float d = length(max(q, 0.0)) + min(max(q.x, q.y), 0.0) - r;
    float m = clamp(0.5 - d / max(feather, 1.0), 0.0, 1.0);
    return image.eval(coord) * half(m);
}
